import pathlib,json,hashlib,collections
p=pathlib.Path('/home/vrondelli/projects/cyberAlchemy-v2/implementation/agent-reasoning-engine/benchmarks/glm-episodes-v1/evidence/expanded-validation-2026-09-07')
r=json.loads((p/'result.json').read_text());m=json.loads((p/'manifest.json').read_text())
for x in m['sources']:assert hashlib.sha256(pathlib.Path(x['path']).read_bytes()).hexdigest()==x['sha256']
trials=[];diffs=[];unknown=0;groups=collections.defaultdict(list)
for t in r['trials']:
 d=p/f"trial-{t['index']:02d}";a=t['report']['arms'][0];c=json.loads((d/'arm-0/completed.json').read_text());v=json.loads((d/'arm-0/visible-trace.json').read_text());heads=[h['soft_headroom_tokens'] for h in c.get('dispatch_headroom',[])];gate=v.get('completion_gate') or {}
 reasons=a.get('reasons',[]) or (c.get('verification') or {}).get('reason_codes',[])
 row={k:t[k] for k in ['index','repetition','episode','policy','soft_limit']};row.update(repair=a['verified_repair'],continuity=a['continuity']['passed'],recycles=c['recycles'],minimum_headroom=min(heads) if heads else None,reasons=reasons,gate_passed=gate.get('passed',False),candidate_accepted=(d/'arm-0/candidate.json').exists(),metrics=t['report']['totals'])
 trials.append(row);groups[(t['episode'],t['soft_limit'])].append(row)
 for receipt in v['receipts']:
  if receipt['kind']!='model':continue
  if isinstance(receipt.get('input_tokens'),int) and isinstance(receipt.get('reserved_input_tokens'),int):diffs.append(receipt['input_tokens']-(receipt['reserved_input_tokens']-512))
  else:unknown+=1
repairs=sum(t['repair'] for t in trials);long=[t for t in trials if t['episode']=='retention-long-window' and t['soft_limit']==12000];heads=[t['minimum_headroom'] for t in trials if t['minimum_headroom'] is not None]
criteria={'all_48_valid':len(trials)==48 and r['status']=='COMPLETED','at_least_44_repairs':repairs>=44,'each_task_window_3_of_4':len(groups)==12 and all(len(g)==4 and sum(t['repair'] for t in g)>=3 for g in groups.values()),'all_accepted_candidates_pass_gate':all(t['gate_passed'] for t in trials if t['candidate_accepted']),'zero_input_reservation_overruns':not any('input-reservation' in str(t['reasons']) for t in trials) and all(d<=512 for d in diffs),'positive_admitted_headroom':bool(heads) and min(heads)>0,'four_long_12k_continuity':len(long)==4 and all(t['continuity'] for t in long)}
s={'authority_effect':'none','status':r['status'],'planned':48,'completed':len(trials),'repairs':repairs,'completion_gate_passes':sum(t['gate_passed'] for t in trials),'continuity_passes':sum(t['continuity'] for t in trials),'recycled_trials':sum(t['recycles']>0 for t in trials),'no_recycle_trials':[t['index'] for t in trials if t['recycles']==0],'minimum_headroom':min(heads) if heads else None,'model_attempts':sum(t['metrics']['model_attempts'] for t in trials),'tokenizer_attempts':sum(t['metrics']['tokenizer_attempts'] for t in trials),'paired_usage_samples':len(diffs),'unknown_usage_samples':unknown,'maximum_tokenizer_underestimate':max(diffs) if diffs else None,'criteria':criteria,'pilot_criteria_met':all(criteria.values()),'trials':trials,'open_questions_ref':'PLAN.md#open-questions'}
(p/'summary.json').write_text(json.dumps(s,indent=2)+'\n')
lines=['# Expanded v8 validation results','',f"Completed {len(trials)}/48. Repairs: {repairs}; completion gate passes: {s['completion_gate_passes']}; continuity: {s['continuity_passes']} across {s['recycled_trials']} recycled trials. Pilot criteria met: {s['pilot_criteria_met']}.",'','| Task | Window | Repairs | Continuity |','| --- | ---: | ---: | ---: |']
for (task,limit),g in sorted(groups.items()):lines.append(f"| {task} | {limit} | {sum(t['repair'] for t in g)}/{len(g)} | {sum(t['continuity'] for t in g)}/{len(g)} |")
lines+=['','| Predeclared criterion | Passed |','| --- | --- |']
for k,v in criteria.items():lines.append(f'| {k} | {v} |')
lines+=['',f"Calls: {s['model_attempts']} model, {s['tokenizer_attempts']} tokenizer. Minimum admitted soft headroom: {s['minimum_headroom']} tokens. Maximum measured tokenizer underestimate: {s['maximum_tokenizer_underestimate']} across {len(diffs)} paired receipts; {unknown} unknown usage receipts excluded.",'','| Trial | Repair | Continuity | Gate | Reasons |','| --- | --- | --- | --- | --- |']
for t in trials:lines.append(f"| [trial-{t['index']:02d}](trial-{t['index']:02d}/checked-report.json) | {t['repair']} | {t['continuity']} | {t['gate_passed']} | {', '.join(t['reasons'])} |")
lines+=['','Source hashes matched before and after each trial and at aggregation. No retries, replacement arms, or runtime/fixture/default changes. Local checks: 378 passed, zero failed, one optional report-input test skipped; every live report was checked. The [manifest](manifest.json) and [plan](PLAN.md) froze the schedule and criteria before calls. Raw report inputs remain in /tmp/are-glm-expanded-validation; visible exports omit raw message history and provider reasoning. Reports verify recorded oracle evidence, not a fresh oracle replay.','','These four tasks were previously used for tuning. This is expanded repeatability evidence, not unseen-task generalization. Trials without recycling provide no recycling coverage. Observable admission and recovery cannot prove absence of provider-internal compaction. No pilot or default activation was performed.','','## Open Questions','','See the [predeclared plan](PLAN.md#open-questions). Any failed criteria require diagnosis before a pilot recommendation.','']
